}

package com.company.generated.units.u2e52a65fe1ce;

import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

public class ValidationFailedStepTest {

    @Test
    public void testValidationFailedExecution() {
        ValidationFailedInput input = new ValidationFailedInput();
        ValidationFailedStep step = new ValidationFailedStep();

        ValidationFailedResult result = step.execute(input);

        assertNotNull(result);
        assertEquals(0, result.getReturnCode());
        assertEquals("10", result.getErrorCategory());
        assertEquals("2", result.getErrorNumber());
        assertEquals("Validation failed: required field missing or invalid", result.getErrorDescription());
    }
}
